import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"62、【小过】 艮下震上","description":"周易口诀义 - 62、【小过】 艮下震上","frontmatter":{"title":"62、【小过】 艮下震上","description":"周易口诀义 - 62、【小过】 艮下震上"},"headers":[],"relativePath":"zh/classics/koujueyi/064.md","filePath":"zh/classics/koujueyi/064.md"}'),r={name:"zh/classics/koujueyi/064.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_62、【小过】-艮下震上" tabindex="-1">62、【小过】 艮下震上 <a class="header-anchor" href="#_62、【小过】-艮下震上" aria-label="Permalink to “62、【小过】 艮下震上”">​</a></h1><p>彖曰：「小过」，小者过而亨也。过以「利贞」，与时行也。柔得中，是以小事吉也；刚失位而不中，是以不可大事也。有飞鸟之象焉，「飞鸟遗之音，不宜上，宜下，大吉」，上逆而下顺也。</p><p>象曰：山上有雷，小过，君子以行过乎恭，丧过乎哀，用过乎俭。</p><p>初六，飞鸟以凶。</p><p>象曰：「飞鸟以凶」，不可如何也。</p><p>六二，过其祖，遇其妣；不及其君，遇其臣，无咎。</p><p>象曰：「不及其君」，臣不可过也。</p><p>九三，弗过防之，从或戕之，凶。</p><p>象曰：「从或戕之」，凶如何也！</p><p>九四，无咎，弗过遇之，往厉必戒，勿用永贞。</p><p>象曰：「弗过遇之」，位不当也。「往厉必戒」，终不可长也。</p><p>六五，密云不雨，自我西郊，公弋取彼在穴。</p><p>象曰：「密云不雨」，已上也。</p><p>上六，弗遇过之，飞鸟离之，凶，是谓灾眚。</p><p>象曰：「弗遇过之」，已亢也。</p><p>解读</p><p>「小过亨利贞」者，「小过」者，过于小事，故谓「小过」也；以小事而济用，物乃可通，故曰「亨」也；顺时矫俗，利在归正，故曰「利贞」也。「可小事，不可大事」者，世既小通，即可正以小事，不可正以大事也。「飞鸟遗之音，不宜上，宜下，大吉」者，鸟之所栖，止于林泽，飞而向上，则入杳冥，羽翮摧颓，遗其音响，哀以思处，愿求所安，故不止则愈困，下则栖于林薮，故曰「不宜上，宜下，大吉」也。此论上乘刚，逆也；下承阳，顺也；故君子为过矫之行，上则逆鳞，下则执柔守顺，故以飞鸟上下而取义焉。</p><p>象曰「山上有雷，小过」者，雷本出震于地上，今既出至山上，过其本处，故曰「小过」也。「君子以行过乎恭，丧过乎哀，用过乎俭」者，小过之世，戒其所过，小人居之，则慢易奢僭，故君子为过矫之行，过乎恭敬；丧孝之礼，过乎哀戚；费用之宜，过于俭约之谓也。</p><p>「初六，飞鸟以凶」者，小过之义，上逆下顺，初应在四，若往就四，则是进于逆也，同于飞鸟，上而无所措足，所以致凶。</p><p>「六二，过其祖，遇其妣，不及其君，遇其臣，无咎」者，过而得之，谓其遇也。六二居初之上，而居中位，是过于初而遇六二也。祖，始也，谓初也；妣，母之称也。六二居中履正，故谓之「妣」矣。己过初遇二位，遇母之内处，故曰「过其祖，遇其妣」。而得位处中，不至于僭，终守臣位，安可有咎？故曰「不及其君，遇其臣，无咎」也。</p><p>「九三，弗过防之，从或戕之，凶」者，小过之世，大者不能立德，故令小者僭过，骄慢陵上也。九三以阳当位，又处下卦之上，固合防遏小人，不令奢僭，而九三更应上六，与小人同情，反为小人所害也，故曰「弗过防之，从或戕之，凶」也。戕者，杀害之义也。</p><p>「九四，无咎，弗过遇之，往厉必戒，勿用永贞」者，居小过之世，小人有过差之行，须大德之人防闲遏绝，不令过差。今九四虽复阳爻而不居位，故其所过咎，责不在己，故得「无咎」。九四所以得免咎者，以其失位在上卦之下，不为过厚之行，故得遇其无咎之宜，故曰「无咎」。弗过，遇之也。既无防止遏制之能，自守其位，则免咎而已。若有所往，则致危厉，故曰「往厉」也。不交于物，物亦不亲，既无人相亲，是无援助，欲有所往，必致危厉，无所告救，故必自戒慎，以全其身，故曰「必戒」也。既不能裁制小人，亦不可任用，以其如此，故不足长行其正，故曰「弗用永贞」也。</p><p>六五，密云不雨，自我西郊，公弋取彼在穴者。小过者，小过于大也。阴居阳位，是小者过于大，阴之盛矣。阴止于上，阳气不通，虽复至盛，密云止在西郊，而不能降其雨。以人事明之，是阴柔之主，以处尊位，未能施其风教，恩惠及下，故曰「密云不雨，自我西郊」也。公者，臣之极贵也。五极阴盛，故称「公」也。小过之时，其过犹小，是不能大作，犹为隐伏。以小德之才，治小过之失，能获在穴隐伏之物，又如公之弋猎而获隐伏之兽，故曰「公弋取彼在穴」也。</p><p>上六：弗遇过之，飞鸟离之，凶。是谓灾眚者，处于小过之极，是小人过甚，不知限际，随至穴极，过至穴，无所复遇，故曰「弗遇过之」也。以小人之行，不守限量，过而不已，遂遭害网，亦如飞鸟飞而不已，无所栖托，必罹矰缴，所以凶矣，故曰「飞鸟离之，凶」。过于亢极，以罹其凶，是谓不慎其身，灾眚斯及，复何恨哉？故曰「是为灾眚」。王注：过至于亢，将何所遇？飞而不已，将何所托也？</p>',24)])])}const u=e(r,[["render",i]]);export{h as __pageData,u as default};
